<?php
namespace App\Livewire\Verification;
use App\Domain\Documents\Services\AuthorizedDocumentQuery;use App\Domain\Verification\Services\VerificationWorkflow;use App\Models\DocumentVerification;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.app')]
class ReviewVerification extends Component{public DocumentVerification $verification;public string $reason_code='',$remarks='';public bool $confirmComplete=false;public function mount(DocumentVerification $verification,AuthorizedDocumentQuery $authorized,VerificationWorkflow $workflow):void{abort_unless(app(\App\Domain\Authorization\Services\PermissionResolver::class)->allows(auth()->user(),'documents.verify'),403);abort_unless($authorized->for(auth()->user())->whereKey($verification->document_id)->exists(),403);$this->verification=$verification->load(['document.currentVersion.files','document.documentType','document.district','document.revenueCircle','version','history']);if($verification->status->value==='PENDING')$workflow->start($verification,auth()->id());}public function approve(VerificationWorkflow $workflow):void{$this->validate(['confirmComplete'=>['accepted'],'remarks'=>['nullable','string','max:5000']]);$workflow->approve($this->verification->fresh('version'),auth()->id(),$this->remarks?:null);session()->flash('success','Verification stage approved.');$this->redirectRoute('verification.queue',navigate:true);}public function reject(VerificationWorkflow $workflow):void{$this->validate(['reason_code'=>['required','string','max:80'],'remarks'=>['required','string','min:5','max:5000']]);$workflow->reject($this->verification->fresh('version'),auth()->id(),$this->reason_code,$this->remarks);session()->flash('success','Document returned/rejected with recorded reason.');$this->redirectRoute('verification.queue',navigate:true);}public function render(){return view('livewire.verification.review-verification');}}
